"use client";
import { useState } from "react";
import Image from "next/image";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import axios from "axios";
import { Formik, Form, Field } from "formik";
import * as Yup from "yup";

const fetchCategories = async ({ queryKey }) => {
  const [, page, search] = queryKey;
  const { data } = await axios.get(
    `http://localhost:8080/api/v1/categories?page=${page}&size=10&categoryName=${search || ""}`
  );
  return data.data.content; // Assuming data.data.content contains the categories list
};

const Categories = () => {
  const [page, setPage] = useState(0);
  const [search, setSearch] = useState("");
  const [modalData, setModalData] = useState(null);
  const queryClient = useQueryClient();

  // Fetch categories
  const { data: categories, isLoading } = useQuery({
    queryKey: ["categories", page, search],
    queryFn: fetchCategories,
    keepPreviousData: true,
  });

  // Mutation for deleting a category
  const deleteCategoryMutation = useMutation({
    mutationFn: async (categoryId) => {
      await axios.patch(`http://localhost:8080/api/v1/categories/${categoryId}/delete`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["categories"]);
    },
  });

  // Mutation for updating a category
  const updateCategoryMutation = useMutation({
    mutationFn: async (formData) => {
      const response = await axios.patch(
        `http://localhost:8080/api/v1/categories/${formData.get("categoryId")}/update`,
        formData,
        { headers: { "Content-Type": "multipart/form-data" } }
      );
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["categories"]);
      setModalData(null); // Close modal after success
    },
  });

  if (isLoading) return <p>Loading categories...</p>;

  return (
    <div className="p-4 text-gray-400">
      {/* Search Bar */}
      <input
        type="text"
        placeholder="Search category..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        className="mb-4 p-2 border rounded w-full"
      />

      {/* Categories List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {categories?.map((category) => (
          <div key={category.id} className="border p-4 flex items-center rounded-lg shadow-md">
            {/* Category Image */}
            {category.imageUrl ? (
              <Image src={category.imageUrl} width={100} height={100} alt={category.categoryName} className="rounded-lg" />
            ) : (
              <div className="w-[100px] h-[100px] bg-gray-200 flex items-center justify-center">No Image</div>
            )}

            {/* Category Details */}
            <div className="ml-4 flex-1">
              <p className="text-gray-500 font-bold">{category.categoryName}</p>
              <div className="flex gap-2 mt-2">
                <button onClick={() => setModalData(category)} className="px-3 py-1 bg-blue-500 text-white rounded">
                  Edit
                </button>
                <button
                  onClick={() => deleteCategoryMutation.mutate(category.id)}
                  className="px-3 py-1 bg-red-500 text-white rounded"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Edit Modal */}
      {modalData && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          <div className="bg-white p-6 rounded-lg shadow-lg w-96">
            <h2 className="text-xl font-bold mb-4">Edit Category</h2>
            <Formik
              initialValues={{ categoryName: modalData.categoryName, image: null }}
              validationSchema={Yup.object({
                categoryName: Yup.string().required("Category name is required"),
                image: Yup.mixed()
                  .test("fileSize", "File too large (max 1MB)", (value) => !value || (value.size <= 1048576))
                  .test(
                    "fileType",
                    "Only JPG, PNG, JPEG, and GIF are allowed",
                    (value) => !value || ["image/jpeg", "image/png", "image/gif"].includes(value.type)
                  ),
              })}
              onSubmit={(values) => {
                const formData = new FormData();
                formData.append("categoryId", modalData.id);
                formData.append("categoryName", values.categoryName);
                if (values.image) {
                  formData.append("file", values.image);
                }
                updateCategoryMutation.mutate(formData);
              }}
            >
              {({ setFieldValue }) => (
                <Form>
                  <label className="block mb-2">Category Name:</label>
                  <Field name="categoryName" className="border p-2 w-full rounded" />
                  
                  <label className="block mt-4 mb-2">Change Image:</label>
                  <input
                    type="file"
                    accept="image/jpeg, image/png, image/gif"
                    onChange={(event) => setFieldValue("image", event.currentTarget.files[0])}
                    className="border p-2 w-full rounded"
                  />

                  {/* Image Preview */}
                  {modalData.imageUrl && (
                    <div className="mt-2">
                      <p className="text-sm">Current Image:</p>
                      <Image src={modalData.imageUrl} width={100} height={100} alt="Current" />
                    </div>
                  )}

                  <div className="flex justify-end mt-4">
                    <button type="submit" className="bg-green-500 text-white px-4 py-2 rounded">
                      Save
                    </button>
                    <button
                      type="button"
                      onClick={() => setModalData(null)}
                      className="ml-2 bg-gray-500 text-white px-4 py-2 rounded"
                    >
                      Cancel
                    </button>
                  </div>
                </Form>
              )}
            </Formik>
          </div>
        </div>
      )}
    </div>
  );
};

export default Categories;
